"""Build the GEGD test fixtures. Every byte here is SYNTHETIC.

    python tests/fixtures/gegd/make_fixtures.py            # rewrite this folder
    python tests/fixtures/gegd/make_fixtures.py /tmp/out   # write elsewhere

This repo is public, and real GEGD responses carry things that must not be in it:
licensed-catalog identifiers, factory order numbers, third-party vendor records,
and (in some endpoints) other users' e-mail addresses. So no captured response is
ever copied here. Instead this script writes FeatureCollections that follow the
real ``Maxar:FinishedFeature`` schema — same attribute names, types, units and
quirks — with made-up values:

  * featureIds are uuid5 of a fixed test namespace, catalog ids start ``B0F``/
    ``10F``/``D0F`` (prefixes no real sensor uses), footprints are rectangles laid
    out in km around the event, and order-number and project fields are left out.
  * The Iliamna-shaped set reproduces the dates, off-nadir angles, sun and
    processing levels the live archive showed for the 2026-08-08 event (the
    08-01 00:18Z WV01 pre that Alaska calls 07-31; the 08-26 / 08-31 WV02 posts;
    the 09-22 in-track stereo pair), plus the records the tab must refuse or
    demote: a Vivid mosaic, a legacy multi-date mosaic tile, a third-party SAR
    strip, a strip outside the search circle, coarse-DEM and low-sun strips.
  * The third-party record carries isThirdParty/sensorType but no productName:
    the live value is the very string the fixture scanner bans, so the parser's
    handling of that literal is tested from an in-memory record instead.
  * Error bodies are the server's own short public texts (401/403/400), which
    carry nothing account-specific; correlation ids are zeros.

Every file carries a marker (``"_synthetic": true`` in JSON, an XML comment, a
``# _synthetic`` line in text), and tests/test_gegd_fixtures_clean.py fails on any
fixture without one, on anything key-shaped, and on any file this script would
not have written byte-for-byte. Stdlib only, deterministic output.
"""
import json
import math
import os
import sys
import uuid
from datetime import datetime, timedelta, timezone

HERE = os.path.dirname(os.path.abspath(__file__))
GENERATOR = "tests/fixtures/gegd/make_fixtures.py"
NOTE = "SYNTHETIC test fixture: made-up values in the real GEGD schema. Not a captured response."
MARK_TXT = f"# _synthetic: generated by {GENERATOR} (not a captured response)"
MARK_XML = f"<!-- _synthetic: generated by {GENERATOR} (not a captured response) -->"
STAMP = "2026-10-13T00:00:00.000Z"          # fixed, so output is reproducible

NS = uuid.uuid5(uuid.NAMESPACE_URL, "landslide-groundtruth/tests/fixtures/gegd")
KM_PER_DEG = 111.32

# ---------------------------------------------------------------- events

ILIAMNA = dict(name="Iliamna-shaped (synthetic)", lat=60.0265, lon=-153.0559,
               origin_utc="2026-08-08T13:00:00Z", r_km=5.0, pre_days=365, post_days=90)
KNIK = dict(name="Knik-shaped (synthetic)", lat=61.15, lon=-148.25,
            origin_utc="2026-08-09T09:30:00Z", r_km=5.0, pre_days=365, post_days=90)
PETERS = dict(name="Peters-Dome-shaped (synthetic)", lat=63.07, lon=-151.0,
              origin_utc="2023-09-13T12:00:00Z", r_km=5.0, pre_days=365, post_days=90)

# Per sensor: (catalog-id digit, bits per pixel, swath km) — plausible, not exact.
SENSORS = {"WV01": ("2", 8, 17.6), "WV02": ("3", 8, 16.4), "WV03": ("4", 8, 13.1),
           "GE01": ("5", 8, 15.2)}


def fid(event, tag):
    return str(uuid.uuid5(NS, f"{event}/{tag}"))


def _t(s):
    return datetime.strptime(s.replace("Z", ""), "%Y-%m-%dT%H:%M:%S.%f" if "." in s
                             else "%Y-%m-%dT%H:%M:%S").replace(tzinfo=timezone.utc)


def _z(d, ms=True):
    return d.strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z" if ms else d.strftime("%Y-%m-%dT%H:%M:%SZ")


def rect(ev, cx, cy, w, l, ang=0.0):
    """Closed lon/lat ring of a w × l km rectangle centred (cx, cy) km from the
    event, rotated ang degrees clockwise from north."""
    kx = KM_PER_DEG * math.cos(math.radians(ev["lat"]))
    a = math.radians(ang)
    pts = []
    for dx, dy in ((-w / 2, -l / 2), (-w / 2, l / 2), (w / 2, l / 2), (w / 2, -l / 2)):
        x = cx + dx * math.cos(a) + dy * math.sin(a)
        y = cy - dx * math.sin(a) + dy * math.cos(a)
        pts.append([round(ev["lon"] + x / kx, 7), round(ev["lat"] + y / KM_PER_DEG, 7)])
    pts.append(list(pts[0]))
    return pts


def box(ev, x0, y0, x1, y1):
    return rect(ev, (x0 + x1) / 2, (y0 + y1) / 2, x1 - x0, y1 - y0)


def centroid_str(ring):
    pts = ring[:-1]
    lon = sum(p[0] for p in pts) / len(pts)
    lat = sum(p[1] for p in pts) / len(pts)
    return json.dumps({"type": "Point", "coordinates": [round(lon, 10), round(lat, 10)]},
                      separators=(",", ":"))


def optical(ev, event, tag, acq, source, ona, sun_el, sun_az, cloud, level, fp,
            gsd=None, seq=1, b0=True, ce90=None, dem=None, product="DAILY_TAKE"):
    """One optical FinishedFeature in the live attribute order; nulls omitted,
    as the server omits them."""
    sensor = source.split("_")[0]
    digit, bits, _ = SENSORS[sensor]
    t = _t(acq)
    pan = sensor == "WV01"
    gsd = gsd if gsd is not None else (0.596 if pan else 0.5)
    created = t + timedelta(hours=2, minutes=17)
    res = round(gsd / (KM_PER_DEG * 1000.0), 12)
    p = {
        "featureId": fid(event, tag),
        "cloudCover": cloud,
        "offNadirAngle": ona,
        "groundSampleDistance": gsd,
        "groundSampleDistanceUnit": "Meter",
        "source": source,
        "sensorName": sensor,
        "sensorCode": source,
        "rasterType": "Maxar",
        "featureCentroid": centroid_str(fp),
        "bandConfiguration": "P" if pan else "RGB",
        "crs": "EPSG:4326",
        "acquisitionDate": acq,
        "resolutionX": res,
        "resolutionY": res,
        "createdDate": _z(created, ms=False),
        "lastModifiedDate": _z(created + timedelta(minutes=25)),
        "productName": product,
        "usageProductId": 8,
        "dataLayer": "daily_take",
        "radiometricLevel": "Corrected",
        "latestAcquisitionTime": t.strftime("%Y-%m-%dT%H:%M:%S.%f") + "Z",
    }
    if level:
        p["processingLevel"] = level
    p["sensorType"] = "Optical"
    p["sunAzimuth"] = sun_az
    p["bitsPerPixel"] = bits
    p["classification"] = "UNCLASSIFIED"
    p["earliestAcquisitionTime"] = t.strftime("%Y-%m-%dT%H:%M:%S.%f") + "Z"
    p["isPrivate"] = False
    if dem or level:
        p["demCorrection"] = dem or ("Fine DEM" if level == "LV3D" else "Coarse DEM")
    p["imageDescriptor"] = "OrthoRectified3"
    p["panSharpenAlgorithm"] = "NONE" if pan else "UNB"
    p["productType"] = "Ortho"
    p["sunElevation"] = sun_el
    p["radiometricEnhancement"] = "DRA"
    if b0:
        p["legacyIdentifier"] = f"B0F{digit}{seq:012X}"
    else:
        p["legacyIdentifier"] = f"10F{digit}{seq:012X}"
    if ce90 is not None:
        p["ce90Accuracy"] = ce90
    elif level == "LV3D":
        p["ce90Accuracy"] = 8.4
    return feature(p, {"type": "Polygon", "coordinates": [fp]})


def feature(props, geom):
    return {"type": "Feature", "id": props["featureId"], "geometry": geom,
            "geometry_name": "featureGeometry", "properties": props}


def collection(ev, features):
    return {
        "_synthetic": True,
        "_generator": GENERATOR,
        "_note": NOTE,
        "_event": ev,
        "type": "FeatureCollection",
        "features": features,
        "totalFeatures": "unknown",
        "numberReturned": len(features),
        "timeStamp": STAMP,
        "crs": {"type": "name", "properties": {"name": "urn:ogc:def:crs:EPSG::4326"}},
    }


# ---------------------------------------------------------------- the sets

def iliamna():
    ev, e = ILIAMNA, "iliamna"
    fs = [
        # 09-22: an in-track stereo pair 40 s apart; the circle's west edge is off-strip
        optical(ev, e, "0922a", "2026-09-22T21:15:03.463Z", "WV02", 28.5, 29.6, 165.8,
                0.043, "LV3D", rect(ev, 6.0, -12.0, 17.0, 40.0, 4), gsd=0.562, seq=0x922A),
        optical(ev, e, "0922b", "2026-09-22T21:15:43.120Z", "WV02", 27.2, 29.5, 166.0,
                0.04, "LV3D", rect(ev, 6.2, -12.1, 17.0, 40.0, 4), gsd=0.556, seq=0x922B),
    ]
    # Vivid: a multi-year mosaic dated AFTER the event. Never a candidate.
    vivid_geom = {"type": "MultiPolygon",
                  "coordinates": [[box(ev, -30, -20, 0, 20)], [box(ev, 0, -20, 30, 20)]]}
    fs.append(feature({
        "featureId": fid(e, "vivid"), "cloudCover": 0, "offNadirAngle": 0,
        "groundSampleDistance": 0.3, "groundSampleDistanceUnit": "Meter",
        "source": "MULTIPLE", "sensorName": "Multiple", "sensorCode": "MULTIPLE",
        "rasterType": "Mosaic Product",
        "featureCentroid": centroid_str(box(ev, -30, -20, 30, 20)),
        "bandConfiguration": "BGRN", "crs": "EPSG:4326",
        "acquisitionDate": "2026-09-02T22:06:25Z", "createdDate": "2026-09-15T17:29:19Z",
        "lastModifiedDate": "2026-09-15T18:58:23.348Z", "productName": "VIVID_STANDARD_30",
        "usageProductId": 127, "dataLayer": "plus_metro",
        "processingLevel": "VIVID_STANDARD_30 - 1:12,000", "isPrivate": False},
        vivid_geom))
    fs += [
        optical(ev, e, "0831", "2026-08-31T21:30:30.008Z", "WV02", 14.1, 37.9, 170.2,
                0, "LV3D", rect(ev, -2.0, 5.0, 17.0, 38.0, -3), gsd=0.478, seq=0x831),
        optical(ev, e, "0826", "2026-08-26T21:15:32.801Z", "WV02", 20.2, 39.1, 165.0,
                0, "LV3D", rect(ev, 1.0, -3.0, 16.4, 30.0, 2), gsd=0.5, seq=0x826),
    ]
    # third-party SAR (separate licence): hidden unless "Include third-party"
    sar_fp = rect(ev, 1.0, 1.0, 5.0, 5.0, 10)
    fs.append(feature({
        "featureId": fid(e, "0820sar"), "cloudCover": 0,
        "groundSampleDistance": 0.46, "groundSampleDistanceUnit": "Meter",
        "source": "UMBRA", "sensorName": "umbra", "sensorCode": "UMBRA",
        "rasterType": "UMBRA", "featureCentroid": centroid_str(sar_fp),
        "bandConfiguration": "1", "crs": "EPSG:4326",
        "acquisitionDate": "2026-08-20T05:12:44Z", "resolutionX": 4.1e-06,
        "resolutionY": 4.1e-06, "createdDate": "2026-08-20T18:04:28Z",
        "lastModifiedDate": "2026-08-20T18:10:21.658Z", "usageProductId": 8,
        "dataLayer": "umbra", "isThirdParty": True, "sensorType": "Radar",
        "isPrivate": False, "legacyIdentifier": "D0F0000000000820"},
        {"type": "Polygon", "coordinates": [sar_fp]}))
    fs += [
        optical(ev, e, "0801", "2026-08-01T00:18:47.500Z", "WV01", 29.6, 43.2, 218.0,
                0.007, "LV3D", rect(ev, -3.0, 2.0, 17.6, 30.0, -6), seq=0x801),
        # inside the padded search BOX but entirely outside the circle
        optical(ev, e, "0715out", "2026-07-15T21:20:00Z", "WV03", 16.0, 50.0, 171.0,
                0.01, "LV3D", box(ev, 4.0, 4.0, 14.0, 14.0), gsd=0.31, seq=0x715),
        optical(ev, e, "0710", "2026-07-10T21:40:00Z", "WV02", 24.0, 51.0, 172.0,
                0.31, "LV3D", rect(ev, 2.0, 8.0, 16.4, 30.0, 1), seq=0x710),
        optical(ev, e, "0520", "2026-05-20T21:49:19.140Z", "WV02", 12.8, 50.1, 175.0,
                0.148, "LV3D", rect(ev, -1.0, -6.0, 16.4, 34.0, -2), gsd=0.47,
                seq=0x520, b0=False),
        # records older than ~April 2026 carry no processingLevel
        optical(ev, e, "1021lowsun", "2025-10-21T22:10:00Z", "WV01", 22.0, 12.5, 190.0,
                0, None, rect(ev, 0.0, 0.0, 17.6, 28.0, 0), seq=0x1021, b0=False),
        optical(ev, e, "0928", "2025-09-28T21:20:00Z", "WV03_VNIR", 18.0, 30.5, 168.0,
                0.02, None, rect(ev, 4.0, 3.0, 13.1, 25.0, 0), gsd=0.32, seq=0x928, b0=False),
        # coarse DEM: its ce90Accuracy is the junk value the live LV2A records carry
        optical(ev, e, "0830lv2a", "2025-08-30T21:55:00Z", "GE01", 34.0, 38.0, 178.0,
                0, "LV2A", rect(ev, -4.0, -2.0, 15.2, 25.0, 5), seq=0x830, b0=False,
                ce90=0.0014, dem="Coarse DEM"),
        optical(ev, e, "0812hi", "2025-08-12T22:05:00Z", "WV02", 41.0, 41.0, 182.0,
                0.02, None, rect(ev, 0.0, 0.0, 16.4, 30.0, 0), seq=0x812, b0=False),
    ]
    # Legacy mosaic tile: five days of pixels under one date, east of the epicentre.
    rdog_fp = box(ev, 2.9, -20.0, 40.0, 30.0)
    fs.append(feature({
        "featureId": fid(e, "rdog"), "cloudCover": 0, "groundSampleDistance": 0.5,
        "groundSampleDistanceUnit": "Meter", "source": "WV01", "sensorName": "WV01",
        "sensorCode": "WV01", "rasterType": "Strip", "featureCentroid": centroid_str(rdog_fp),
        "crs": "EPSG:32605", "acquisitionDate": "2021-03-27T00:51:39Z",
        "resolutionX": 0.5, "resolutionY": -0.5, "createdDate": "2023-01-26T17:15:32Z",
        "lastModifiedDate": "2025-03-29T07:29:06.119Z", "productName": "RDOG_BASE",
        "usageProductId": 9, "copyright": "Image Copyright 2023 DigitalGlobe Inc",
        "dataLayer": "rdog_base", "latestAcquisitionTime": "2021-04-01T00:36:53.000000",
        "spatialAccuracy": "1:12,000", "sensorType": "Optical",
        "classification": "UNCLASSIFIED",
        "earliestAcquisitionTime": "2021-03-27T00:51:39.000000", "isPrivate": False,
        "licenseType": "nextview", "outputMosaic": True, "productType": "Panchromatic",
        "isEnvelopeGeometry": False, "legacyIdentifier": "20F0000000000327",
        "niirs": 4, "hasSeamlines": True, "ce90Accuracy": 8.4},
        {"type": "Polygon", "coordinates": [rdog_fp]}))
    return collection(ev, fs)


KNIK_PRE_LV2A = ("0502lv2a", "2026-05-02T21:30:05Z", "WV01", 38.5, 40.0, 175.0, 0,
                 "LV2A", (-1.0, 0.0, 17.6, 30.0, 0))


def _knik_lv2a():
    ev = KNIK
    tag, acq, src, ona, el, az, cl, lvl, (cx, cy, w, l, a) = KNIK_PRE_LV2A
    return optical(ev, "knik", tag, acq, src, ona, el, az, cl, lvl, rect(ev, cx, cy, w, l, a),
                   seq=0x502, ce90=0.0014, dem="Coarse DEM")


def knik():
    ev, e = KNIK, "knik"
    fs = [
        optical(ev, e, "0922", "2026-09-22T21:10:40Z", "WV03_VNIR", 23.0, 25.8, 170.0,
                0.12, "LV3D", rect(ev, 2.0, 1.0, 13.1, 22.0, -2), gsd=0.33, seq=0x922),
        optical(ev, e, "0902", "2026-09-02T21:05:12.250Z", "WV03_VNIR", 17.5, 35.2, 168.0,
                0.05, "LV3D", rect(ev, 0.0, -2.0, 13.1, 22.0, 3), gsd=0.33, seq=0x902),
        _knik_lv2a(),
        optical(ev, e, "0410lowsun", "2026-04-10T21:45:00Z", "GE01", 26.0, 11.0, 176.0,
                0.03, "LV3D", rect(ev, 1.0, 1.0, 15.2, 20.0, 0), seq=0x410),
    ]
    return collection(ev, fs)


def knik_nearest_pre():
    """What the count=1 'nearest before t0' query returns for Knik with a 60-day
    before-window: the 05-02 coarse-DEM strip (the same record as in wfs_knik)."""
    ev = dict(KNIK, pre_days=60)
    return collection(ev, [_knik_lv2a()])


def peters_dome():
    return collection(PETERS, [])


def hits_canary():
    return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + MARK_XML
            + "<wfs:FeatureCollection xmlns:wfs=\"http://www.opengis.net/wfs/2.0\" "
            "xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" "
            "numberMatched=\"34\" numberReturned=\"0\" timeStamp=\"" + STAMP + "\" "
            "xsi:schemaLocation=\"http://www.opengis.net/wfs/2.0 "
            "http://schemas.opengis.net/wfs/2.0/wfs.xsd\"/>\n")


def ows_exception(text, code="NoApplicableCode"):
    return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + MARK_XML
            + "<ows:ExceptionReport xmlns:ows=\"http://www.opengis.net/ows/1.1\" "
            "version=\"2.0.0\">\n  <ows:Exception exceptionCode=\"" + code + "\">\n"
            "    <ows:ExceptionText>" + text + "</ows:ExceptionText>\n"
            "  </ows:Exception>\n</ows:ExceptionReport>\n")


def wms_service_exception():
    # WMS 1.1.1 form, as returned for exceptions=application/vnd.ogc.se_xml
    return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + MARK_XML
            + "<ServiceExceptionReport version=\"1.1.1\">\n  <ServiceException "
            "code=\"InvalidParameterValue\">\n    Could not parse CQL filter list.\n"
            "    Encountered \"NOT\" at line 1, column 120.\n  </ServiceException>\n"
            "</ServiceExceptionReport>\n")


def _json_body(obj):
    d = dict(obj)
    d["_synthetic"] = True
    return d


# ---------------------------------------------------------------- write

def files():
    """{name: str content} for every fixture, in a stable order."""
    out = {}

    def js(name, obj):
        out[name] = json.dumps(obj, indent=1, ensure_ascii=True) + "\n"

    js("wfs_iliamna.json", iliamna())
    js("wfs_knik.json", knik())
    js("wfs_knik_nearest_pre.json", knik_nearest_pre())
    js("wfs_empty_petersdome.json", peters_dome())
    out["wfs_hits_canary.xml"] = hits_canary()
    # error bodies: the server's own short texts
    out["err_401_key_not_sent.txt"] = (
        "No JWT bearer token found in HTTP Authorization request header or API Key "
        "provided\n" + MARK_TXT + "\n")
    js("err_401_unauthorized.json", _json_body({"message": "Unauthorized"}))
    js("err_401_unrecognized_token.json", _json_body({
        "title": "Unauthorized", "status": "401", "detail": "Unrecognized token",
        "parameters": {"correlationId": "Root=1-00000000-000000000000000000000000"}}))
    out["err_403_malformed_token.txt"] = (
        "An error occurred while attempting to decode the Jwt: Malformed token\n"
        + MARK_TXT + "\n")
    out["err_400_bad_data_query.xml"] = ows_exception("Bad data query.")
    out["ogc_service_exception.xml"] = wms_service_exception()
    return out


def build(outdir=HERE):
    """Write every fixture into outdir; returns the sorted file names."""
    os.makedirs(outdir, exist_ok=True)
    names = []
    for name, text in files().items():
        path = os.path.join(outdir, name)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        names.append(name)
    return sorted(names)


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else HERE
    for n in build(target):
        print(os.path.join(target, n))
